Complete the nested sealed class pattern:

```dart
%order% class %order% {
}

class Number %order% Expr {
  final double value;
  Number(this.value);
}

class BinaryOp %order% Expr {
  final Expr left;
  final String operator;
  final Expr right;
  BinaryOp(this.left, this.operator, this.right);
}

double evaluate(Expr expr) {
  return %order% (expr) {
    Number(value: var v) => v,
    BinaryOp(left: var l, operator: '+', right: var r) => 
      evaluate(l) + evaluate(r),
    BinaryOp(left: var l, operator: '-', right: var r) => 
      evaluate(l) - evaluate(r),
  };
}
```

What will this expression evaluator return?

```dart
sealed class Expr {
}

class Num extends Expr {
  final int value;
  Num(this.value);
}

class Add extends Expr {
  final Expr left, right;
  Add(this.left, this.right);
}

int eval(Expr expr) {
  return switch (expr) {
    Num(value: var v) => v,
    Add(left: var l, right: var r) => eval(l) + eval(r),
  };
}

void main() {
  print(eval(Add(Num(3), Num(4))));
}
```

